SELECT a.admission_type, s.stay_length, p.gender, d.diagnosis_code, AVG(v.value) AS average_value FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN labevents v ON a.subject_id = v.subject_id AND a.hadm_id = v.hadm_id JOIN stay s ON a.stay_id = s.stay_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 74 AND d.diagnosis_code = '415051000' AND v.valueuom != 'I' AND s.stay_length BETWEEN 1 AND 7 AND a.admission_type IN ('ED', 'URGENT', 'ELECTIVE') GROUP BY a.admission_type, s.stay_length, p.gender, d.diagnosis_code ORDER BY a.admission_type, s.stay_length, p.gender, d.diagnosis_code NULLS LAST;